COMMENT ON SCHEMA exhibition_portal IS
    'Database objects for the Sarv Biolabs exhibition and reusable inquiry portal.';
COMMENT ON TABLE inquiries IS
    'The portal source of truth for a visitor submission. A route extension records supplier or purchase-specific workflow.';
COMMENT ON TABLE inquiry_parties IS
    'Original visitor-submitted person/company snapshot; canonical contact and organization links are optional.';
COMMENT ON TABLE file_assets IS
    'Metadata-only registry for objects held in secure storage. File bytes are never persisted in PostgreSQL.';
COMMENT ON TABLE location_evidence IS
    'Voluntary consent-backed evidence. Exact coordinates are encrypted and scheduled for purge; raw IP addresses are not stored.';
COMMENT ON TABLE ai_extracted_fields IS
    'Reviewable AI suggestions. Acceptance or correction is required before any value becomes user-confirmed data.';
COMMENT ON TABLE integration_deliveries IS
    'Idempotent outbound delivery outbox and retry record for vendor and marketing destinations.';

COMMIT;
